// data/scientificEvents.ts
// Base d'événements historiques et scientifiques réels, datés (jour/mois/année).
// Utilisée pour afficher « ce jour-là dans l'histoire » sur la page d'accueil.

export interface HistoricalEvent {
  day: number;   // 1-31
  month: number; // 1-12
  year: number;  // négatif = av. J.-C.
  text: string;
  source: string;
  category: 'Naissance' | 'Décès' | 'Découverte' | 'Histoire';
  href?: string; // lien vers la fiche existante, si disponible
}

function formatYear(year: number): string {
  return year < 0 ? `${-year} av. J.-C.` : `${year}`;
}

