const events: HistoricalEvent[] = [...BIRTHS, ...DEATHS, ...DISCOVERIES, ...HISTORY];

/**
 * Retourne un événement réel survenu ce jour-là (jour + mois), toutes années confondues.
 * S'il y a plusieurs correspondances pour la date du jour, le choix est déterministe
 * (basé sur l'année en cours) afin de varier d'une année sur l'autre.
 * Retourne `null` si aucun événement de la base ne correspond exactement à la date du jour.
 */
export function getScientificEventDuJour(date: Date = new Date()): (HistoricalEvent & { yearLabel: string }) | null {
  const day = date.getDate();
  const month = date.getMonth() + 1;
  const matches = events.filter(e => e.day === day && e.month === month);
  if (matches.length === 0) return null;
  const pick = matches[date.getFullYear() % matches.length];
  return { ...pick, yearLabel: formatYear(pick.year) };
}
